import numpy as np
from pathlib import Path
for tag in ['close_093','final_hold_105']:
 p=Path('/app/output/episode')/tag
 for cam in ['left','right']:
  im=np.array(Image.open(p/f'{cam}.png')); dep=np.load(p/f'{cam}_depth.npy'); dep=dep[0] if dep.ndim==3 else dep
  box=(145,108,172,150) if cam=='left' else (148,95,180,140)
  x1,y1,x2,y2=box; a=im[y1:y2,x1:x2];d=dep[y1:y2,x1:x2]
  # Masks cyan, bright white, object red
  masks={
   'cyan':(a[:,:,1]>130)&(a[:,:,2]>130)&(a[:,:,0]<100),
   'white':(a[:,:,0]>180)&(a[:,:,1]>180)&(a[:,:,2]>180),
   'red':(a[:,:,0]>80)&(a[:,:,0]>a[:,:,1]*1.8)&(a[:,:,0]>a[:,:,2]*1.8),
  }
  print(tag,cam)
  for n,m in masks.items():
   yy,xx=np.nonzero(m); print(n,len(xx), 'bbox', None if not len(xx) else (int(xx.min()+x1),int(yy.min()+y1),int(xx.max()+x1),int(yy.max()+y1)),'depth', None if not len(xx) else np.round(np.quantile(d[yy,xx],[.1,.5,.9]),4).tolist())
  # each pixel at visible finger positions along rows
  for y in range(y1+8,y2,3):
   vals=[]
   for x in range(x1,x2):
    r,g,b=im[y,x]
    if g>140 and b>140 and r<100: vals.append((x,round(float(dep[y,x]),3),'c'))
    elif min(r,g,b)>200: vals.append((x,round(float(dep[y,x]),3),'w'))
   if vals: print('row',y,vals)
